@Test
public void testDoubleBlocker() throws Exception {
    final Table table = Table.editor()
            .tableId(new TableId(null, "UNKNOWN", "TABLE"))
            .addColumn(Column.editor().name("COL1").create())
            .create();

    String sql = "update \"UNKNOWN\".\"TABLE\" set \"COL1\" = 'I||am' where \"COL1\" = 'I||am'";
